import{_ as a,o as s,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Mise en cache","description":"","frontmatter":{},"headers":[],"relativePath":"fr/advanced/caching.md","filePath":"fr/advanced/caching.md","lastUpdated":1784903584000}'),c={name:"fr/advanced/caching.md"};function n(r,e,o,l,d,h){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="mise-en-cache" tabindex="-1">Mise en cache <a class="header-anchor" href="#mise-en-cache" aria-label="Permalink to &quot;Mise en cache&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>swag2mcp met en cache les fichiers de spécification téléchargés afin que le serveur MCP démarre plus rapidement lors des exécutions suivantes. Au lieu de télécharger le même fichier de spécification à chaque fois, il réutilise la copie en cache.</p><h2 id="comment-fonctionne-la-mise-en-cache" tabindex="-1">Comment fonctionne la mise en cache <a class="header-anchor" href="#comment-fonctionne-la-mise-en-cache" aria-label="Permalink to &quot;Comment fonctionne la mise en cache&quot;">​</a></h2><p>Lorsque vous ajoutez une spec avec une URL distante, swag2mcp la télécharge et la sauvegarde dans le répertoire <code>cache/</code>. Au prochain démarrage, il vérifie si la copie en cache est encore fraîche. Si c&#39;est le cas, le téléchargement est ignoré.</p><h3 id="ce-qui-est-mis-en-cache" tabindex="-1">Ce qui est mis en cache <a class="header-anchor" href="#ce-qui-est-mis-en-cache" aria-label="Permalink to &quot;Ce qui est mis en cache&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Source</th><th>Comportement</th></tr></thead><tbody><tr><td><strong>URL distante</strong> (http/https)</td><td>Toujours mise en cache. Téléchargée une fois, réutilisée jusqu&#39;à l&#39;expiration du cache.</td></tr><tr><td><strong>Fichier local dans <code>specs/</code></strong></td><td>Utilisé directement depuis le répertoire <code>specs/</code>. Jamais mis en cache — les modifications sont immédiatement visibles.</td></tr><tr><td><strong>Fichier local hors de <code>specs/</code></strong></td><td>Copié dans le cache. Si le fichier source change (heure de modification), le cache est invalidé.</td></tr></tbody></table><h3 id="expiration-du-cache-ttl" tabindex="-1">Expiration du cache (TTL) <a class="header-anchor" href="#expiration-du-cache-ttl" aria-label="Permalink to &quot;Expiration du cache (TTL)&quot;">​</a></h3><p>Chaque fichier en cache reçoit un temps d&#39;expiration aléatoire entre <strong>1 heure et 48 heures</strong>. Le caractère aléatoire empêche tous les fichiers en cache d&#39;expirer en même temps (ce qui provoquerait une ruée de téléchargements).</p><ul><li>Le TTL est réinitialisé à chaque démarrage du serveur MCP</li><li>Si un fichier en cache est encore dans son TTL, il est réutilisé</li><li>Si le TTL a expiré, le fichier est téléchargé à nouveau</li></ul><h3 id="structure-du-cache" tabindex="-1">Structure du cache <a class="header-anchor" href="#structure-du-cache" aria-label="Permalink to &quot;Structure du cache&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/cache/</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.spec    # Fichier de spécification en cache</span></span>
<span class="line"><span>├── a1b2c3d4e5f6a7b8.meta    # Métadonnées (source, TTL, date de mise en cache)</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.spec</span></span>
<span class="line"><span>├── b2c3d4e5f6a7b8c9.meta</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><p>La clé de cache est dérivée de l&#39;URL ou du chemin du fichier de spécification. Chaque fichier en cache a un fichier <code>.meta</code> compagnon qui stocke quand il a été mis en cache et quand il expire.</p><h2 id="gestion-du-cache" tabindex="-1">Gestion du cache <a class="header-anchor" href="#gestion-du-cache" aria-label="Permalink to &quot;Gestion du cache&quot;">​</a></h2><h3 id="forcer-un-rafraichissement" tabindex="-1">Forcer un rafraîchissement <a class="header-anchor" href="#forcer-un-rafraichissement" aria-label="Permalink to &quot;Forcer un rafraîchissement&quot;">​</a></h3><p>Exécutez <code>swag2mcp update</code> pour vider tout le cache et retélécharger tous les fichiers de spécification :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>Cela valide la configuration, vide le cache et télécharge tout à nouveau.</p><h3 id="vider-le-cache-manuellement" tabindex="-1">Vider le cache manuellement <a class="header-anchor" href="#vider-le-cache-manuellement" aria-label="Permalink to &quot;Vider le cache manuellement&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>Cela supprime tous les fichiers de spécification en cache et les réponses d&#39;API sauvegardées. La prochaine fois que vous démarrerez le serveur MCP, toutes les specs seront téléchargées à nouveau.</p><h3 id="nettoyage-automatique" tabindex="-1">Nettoyage automatique <a class="header-anchor" href="#nettoyage-automatique" aria-label="Permalink to &quot;Nettoyage automatique&quot;">​</a></h3><p>Lorsque le serveur MCP démarre (<code>swag2mcp mcp</code>), les réponses d&#39;API sauvegardées de plus de 48 heures sont automatiquement supprimées. Cela empêche le répertoire <code>responses/</code> de croître indéfiniment.</p><h2 id="notes-importantes" tabindex="-1">Notes importantes <a class="header-anchor" href="#notes-importantes" aria-label="Permalink to &quot;Notes importantes&quot;">​</a></h2><ul><li><strong>Les fichiers locaux dans <code>specs/</code> ne sont jamais mis en cache</strong> — si vous modifiez un fichier de spécification directement dans le répertoire <code>specs/</code>, les modifications sont immédiatement visibles sans vider le cache</li><li><strong>Les URL distantes sont toujours mises en cache</strong> — il n&#39;y a aucun moyen de contourner le cache pour les URL distantes, sauf en exécutant <code>swag2mcp update</code> ou <code>swag2mcp clean</code></li><li><strong>Le cache est local</strong> — il est stocké sur le disque et ne se synchronise pas entre les machines. Utilisez <code>swag2mcp export</code> et <code>swag2mcp import</code> pour transférer les specs entre machines</li></ul>`,25)])])}const m=a(c,[["render",n]]);export{p as __pageData,m as default};
